public static int findNthLeapYear(int Y, int N) {
    int count = 0;
    int year = Y;
    while (count < N) {
        if (isLeapYear(year)) {
            count++;
        }
        year++;
    }
    return year;
}

private static boolean isLeapYear(int year) {
    return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
}
