public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int denominator = word1.length() + word2.length();
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

public static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

public static String convertDatesToWeekdays(String date) {
    SimpleDateFormat formatter = new SimpleDateFormat("MM dd yyyy");
    Date inputDate = formatter.parse(date);
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(inputDate);
    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);
    String weekday = "";
    switch (dayOfWeek) {
        case Calendar.SUNDAY:
            weekday = "Sunday";
            break;
        case Calendar.MONDAY:
            weekday = "Monday";
            break;
        case Calendar.TUESDAY:
            weekday = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekday = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekday = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekday = "Friday";
            break;
        case Calendar.SATURDAY:
            weekday = "Saturday";
            break;
    }
    return weekday;
}

